/**
 * robot_config.h - single place for board / robot constants.
 * Target: NUCLEO-G474RE (STM32G474RET6), 4x RoboMaster M3508 + C620 on FDCAN1 @ 1 Mbit/s,
 * velocity commands from a Jetson on USART1.
 */
#ifndef ROBOT_CONFIG_H
#define ROBOT_CONFIG_H

#include "main.h"           /* HAL + CubeMX handles */

/* ---------------- CAN ---------------- */
#define ROBOT_CAN_HANDLE            hfdcan1      /* generated by CubeMX in fdcan.c */
extern FDCAN_HandleTypeDef          ROBOT_CAN_HANDLE;

/* ---------------- Jetson command link (USART1, 921600 8N1, PA9 = TX, PA10 = RX) ---------------- */
#define ROBOT_CMD_UART              huart1       /* generated by CubeMX in usart.c */
extern UART_HandleTypeDef           ROBOT_CMD_UART;
#define CMD_TIMEOUT_MS              200U         /* no valid command for this long -> robot brakes to a stop */
#define INPUT_FALLBACK_POLL_MS      10U          /* inputTask wakes at least this often even without UART activity */

/* ---------------- Control loop ---------------- */
#define CTRL_PERIOD_MS              1U           /* processTask period (C620 feedback is 1 kHz) */

/* ---------------- Chassis (mecanum). Frame: x forward, y left, wz counter-clockwise ---------------- */
#define CHASSIS_WHEEL_RADIUS_M      0.0762f      /* 152 mm mecanum wheel */
#define CHASSIS_HALF_TRACK_M        0.20f        /* half the left-right wheel distance */
#define CHASSIS_HALF_BASE_M         0.20f        /* half the front-rear wheel distance */

/* Which C620 ID drives which wheel */
#define CHASSIS_ID_FL               1
#define CHASSIS_ID_FR               2
#define CHASSIS_ID_RL               3
#define CHASSIS_ID_RR               4
/* +1 if positive motor rotation rolls the robot FORWARD at that wheel, -1 if backward.
   Right-side motors are normally mirrored. Verify with the README bring-up test. */
#define CHASSIS_DIR_FL              (+1.0f)
#define CHASSIS_DIR_FR              (-1.0f)
#define CHASSIS_DIR_RL              (+1.0f)
#define CHASSIS_DIR_RR              (-1.0f)

/* Limits applied to the whole robot, so all four wheels speed up and slow down together */
#define CHASSIS_MAX_LIN_MPS         2.0f         /* max |(vx, vy)|                         */
#define CHASSIS_MAX_ANG_RPS         4.0f         /* max |wz|, rad/s                        */
#define CHASSIS_ACCEL_LIN           3.0f         /* m/s^2, speeding up                     */
#define CHASSIS_DECEL_LIN           4.0f         /* m/s^2, slowing down on command         */
#define CHASSIS_BRAKE_LIN           6.0f         /* m/s^2, stopping after command loss     */
#define CHASSIS_ACCEL_ANG           8.0f         /* rad/s^2                                */
#define CHASSIS_DECEL_ANG           10.0f
#define CHASSIS_BRAKE_ANG           16.0f
#define CHASSIS_MAX_WHEEL_RPM       450.0f       /* if any wheel would exceed this, all four are scaled down together */
/* 1 = drive only when all four motors answer (coast otherwise). Set 0 to bench-test with fewer motors. */
#define CHASSIS_REQUIRE_ALL_MOTORS  1

/* ---------------- Motors ---------------- */
#define M3508_NUM_MOTORS            4            /* C620 IDs 1..4 */
#define M3508_FEEDBACK_TIMEOUT_MS   100U         /* no CAN feedback for this long -> motor offline, cmd = 0 */

/* C620 current command scale: +/-16384 <-> +/-20 A. */
#define M3508_CURRENT_RAW_MAX       16384
#define M3508_CURRENT_A_MAX         20.0f
/* Absolute software ceiling, applied after everything else. Raise to 16384 once the mechanics are proven. */
#define M3508_CURRENT_RAW_LIMIT     10000        /* ~12.2 A */

/* M3508 gearbox 3591:187 = 19.2032:1, 8192-count rotor encoder */
#define M3508_GEAR_RATIO            (3591.0f / 187.0f)
#define M3508_ECD_RANGE             8192
#define M3508_ECD_HALF              4096
#define M3508_TORQUE_CONST_NM_A     0.3f         /* output-shaft torque per amp (DJI datasheet) */
#define M3508_ROTOR_RPM_MAX         9500.0f      /* ~482 rpm at the output shaft, no load */
#define M3508_STOP_RPM              30.0f        /* rotor rpm below which the motor counts as stopped */

/* Speed loop (rotor rpm -> raw current). ki/kd are per second. STARTING POINTS - tune on the real robot. */
#define M3508_SPEED_KP              8.0f
#define M3508_SPEED_KI              60.0f
#define M3508_SPEED_KD              0.0f
#define M3508_SPEED_I_MAX           ((float)M3508_CURRENT_RAW_LIMIT)   /* integrator must be able to hold full load */

/* Angle loop (output-shaft deg -> rotor rpm setpoint). Not used by the chassis; kept for the motor library. */
#define M3508_ANGLE_KP              60.0f
#define M3508_ANGLE_KI              0.0f
#define M3508_ANGLE_KD              0.0f
#define M3508_ANGLE_I_MAX           1000.0f

/* Default per-motor limits, OUTPUT-SHAFT units. The chassis sets the motor ramps to 0 (it ramps the
   whole robot instead); the current limits below are what the wheels actually run with. */
#define M3508_DEF_ACCEL_RPM_S       600.0f
#define M3508_DEF_DECEL_RPM_S       900.0f
#define M3508_DEF_BRAKE_DECEL_RPM_S 1500.0f
#define M3508_DEF_MAX_SPEED_RPM     300.0f
#define M3508_DEF_CURRENT_A         10.0f        /* torque limit while driving           */
#define M3508_DEF_BRAKE_CURRENT_A   10.0f        /* torque limit in motor brake mode     */

#endif /* ROBOT_CONFIG_H */
